def _canonical_json_sha256(value: Mapping[str, Any]) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


RULESET_SHA256 = _canonical_json_sha256(RULESET_SPEC)


class DeltaChatRouteApprovalStateEvaluator(BaseEvaluator):
    """Verify the complete Route Gate workflow through durable read-only state."""

    RULESET_SHA256 = RULESET_SHA256

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        udid = str(
            params.get("udid")
            or getattr(getattr(controller, "runtime", None), "udid", "")
            or ""
        ).strip()
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="evaluation.params.udid is required; no default simulator fallback is allowed",
                metadata={"ruleset_sha256": RULESET_SHA256, "read_only": True},
            )

        expected_ruleset = str(params.get("expected_ruleset_sha256") or "").strip()
        ruleset_check = self._check(
            "ruleset_binding",
            expected_ruleset == RULESET_SHA256,
            steps=[],
            dimension="binding",
            expected=RULESET_SHA256,
            observed=expected_ruleset or None,
            failure_reason="task evaluator ruleset digest does not match the implemented rules",
        )

        observed_parameters = {
            "bundle_id": str(params.get("bundle_id") or ""),
            "fsnotes_bundle_id": str(params.get("fsnotes_bundle_id") or ""),
            "source_simulator_name": str(params.get("source_simulator_name") or ""),
            "ios_device_profile": str(params.get("ios_device_profile") or ""),
            "delta_chat_short_version": str(params.get("delta_chat_short_version") or ""),
            "delta_chat_build_version": str(params.get("delta_chat_build_version") or ""),
            "fsnotes_short_version": str(params.get("fsnotes_short_version") or ""),
            "fsnotes_build_version": str(params.get("fsnotes_build_version") or ""),
            "minimum_message_id": self._int_param(params, "minimum_message_id"),
            "baseline_max_timestamp": self._int_param(params, "baseline_max_timestamp"),
            "fsnotes_baseline_max_timestamp": self._int_param(
                params, "fsnotes_baseline_max_timestamp"
            ),
            "sent_state": self._int_param(params, "sent_state"),
        }
        expected_parameters = {
            "bundle_id": DELTACHAT_BUNDLE_ID,
            "fsnotes_bundle_id": FSNOTES_BUNDLE_ID,
            "source_simulator_name": EXPECTED_SOURCE_SIMULATOR_NAME,
            "ios_device_profile": EXPECTED_IOS_DEVICE_PROFILE,
            "delta_chat_short_version": EXPECTED_DELTACHAT_SHORT_VERSION,
            "delta_chat_build_version": EXPECTED_DELTACHAT_BUILD_VERSION,
            "fsnotes_short_version": EXPECTED_FSNOTES_SHORT_VERSION,
            "fsnotes_build_version": EXPECTED_FSNOTES_BUILD_VERSION,
            "minimum_message_id": DEFAULT_MINIMUM_MESSAGE_ID,
            "baseline_max_timestamp": DEFAULT_BASELINE_MAX_TIMESTAMP,
            "fsnotes_baseline_max_timestamp": DEFAULT_FSNOTES_BASELINE_MAX_TIMESTAMP,
            "sent_state": DEFAULT_SENT_STATE,
        }
        parameter_check = self._check(
            "business_parameter_binding",
            observed_parameters == expected_parameters,
            steps=[],
            dimension="binding",
            expected=expected_parameters,
            observed=observed_parameters,
            failure_reason="task business, application, source, or profile parameters differ from the ruleset",
        )
        if not ruleset_check["pass"] or not parameter_check["pass"]:
            return self._result(
                status=EvalStatus.FAIL,
                message="Delta Chat Route Gate evaluator binding is invalid",
                udid=udid,
                checks=[ruleset_check, parameter_check],
                observed={},
            )

        try:
            delta_identity = self._read_app_identity(udid, DELTACHAT_BUNDLE_ID)
            fsnotes_identity = self._read_app_identity(udid, FSNOTES_BUNDLE_ID)
            identities = [delta_identity, fsnotes_identity]
            expected_identities = list(RULESET_SPEC["stable_binding"]["applications"])
            identity_check = self._check(
                "installed_application_identity",
                identities == expected_identities,
                steps=[],
                dimension="binding",
                expected=expected_identities,
                observed=identities,
                failure_reason="installed bundle identifiers or application versions do not match the bound snapshot",
            )

            app_group_root = _find_shared_app_group_root(
                udid=udid,
                group_id=DELTACHAT_APP_GROUP_ID,
            )
            db_paths = sorted((app_group_root / "accounts").glob("*/dc.db"))
            if len(db_paths) != 1:
                raise RuntimeError(
                    f"expected exactly one bound Delta Chat account database, found {len(db_paths)}"
                )
            documents = self._resolve_fsnotes_documents(
                udid=udid,
                bundle_id=FSNOTES_BUNDLE_ID,
            )
            seed_boundary = max(
                observed_parameters["baseline_max_timestamp"],
                observed_parameters["fsnotes_baseline_max_timestamp"],
            )
            boot_timestamp = self._read_boot_timestamp(udid, seed_boundary)
            checks, observed = self._evaluate_bound_state(
                db_path=db_paths[0],
                fsnotes_documents=documents,
                minimum_message_id=observed_parameters["minimum_message_id"],
                baseline_max_timestamp=observed_parameters["baseline_max_timestamp"],
                fsnotes_baseline_max_timestamp=observed_parameters[
                    "fsnotes_baseline_max_timestamp"
                ],
                sent_state=observed_parameters["sent_state"],
                boot_timestamp=boot_timestamp,
            )
            observed["applications"] = identities
            observed["episode_boundary_timestamp"] = boot_timestamp
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read bound iOS app state: {type(exc).__name__}: {exc}",
                metadata={
                    "task_id": TASK_ID,
                    "udid": udid,
                    "ruleset_sha256": RULESET_SHA256,
                    "exception_type": type(exc).__name__,
                    "read_only": True,
                },
            )

        checks[0:0] = [ruleset_check, parameter_check, identity_check]
        failures = [check for check in checks if not check["pass"]]
        return self._result(
            status=EvalStatus.FAIL if failures else EvalStatus.PASS,
            message=(
                "Delta Chat Route Gate exact bytes, provenance, freshness, and ordered outputs match"
                if not failures
                else "Delta Chat Route Gate durable evidence is missing, stale, extra, or out of order"
            ),
            udid=udid,
            checks=checks,
            observed=observed,
        )

    @classmethod
    def _evaluate_bound_state(
        cls,
        *,
        db_path: Path,
        fsnotes_documents: Path,
        minimum_message_id: int,
        baseline_max_timestamp: int,
        fsnotes_baseline_max_timestamp: int,
        sent_state: int,
        boot_timestamp: float,
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        with cls._sqlite_snapshot(db_path) as snapshot:
            connection = sqlite3.connect(f"file:{snapshot.as_posix()}?mode=ro", uri=True)
            connection.row_factory = sqlite3.Row
            try:
                chat_rows = connection.execute(
                    "SELECT id,type,name,param FROM chats ORDER BY id"
                ).fetchall()
                messages = connection.execute(
                    """
                    SELECT m.id,m.chat_id,m.type,m.state,m.timestamp,
                           COALESCE(m.txt,'') AS txt,COALESCE(m.param,'') AS param,
                           COALESCE(c.name,'') AS chat_name,COALESCE(c.type,0) AS chat_type
                    FROM msgs m
                    LEFT JOIN chats c ON c.id=m.chat_id
                    WHERE m.hidden=0 AND COALESCE(m.deleted,0)=0
                    ORDER BY m.id
                    """
                ).fetchall()
            finally:
                connection.close()

        checks: list[dict[str, Any]] = []
        self_chats = [
            row
            for row in chat_rows
            if int(row["type"] or 0) == 100 and cls._param_value(row["param"], "K") == "1"
        ]
        self_chat_id = int(self_chats[0]["id"]) if len(self_chats) == 1 else None
        checks.append(
            cls._check(
                "bound_saved_messages_chat",
                self_chat_id is not None,
                steps=list(range(41, 80)),
                dimension="final_object",
                expected="exactly one Delta Chat self-chat (type=100, K=1)",
                observed=[
                    {"id": int(row["id"]), "name": str(row["name"])} for row in self_chats
                ],
                failure_reason="Saved Messages self-chat could not be resolved unambiguously",
            )
        )

        baseline_rows = [row for row in messages if int(row["id"]) < minimum_message_id]
        new_saved_rows = [
            row
            for row in messages
            if self_chat_id is not None
            and int(row["chat_id"]) == self_chat_id
            and int(row["id"]) >= minimum_message_id
        ]
        checks.append(
            cls._check(
                "saved_messages_output_count",
                len(new_saved_rows) == 3,
                steps=list(range(41, 80)),
                dimension="final_object",
                expected={"count": 3, "minimum_message_id": minimum_message_id},
                observed={
                    "count": len(new_saved_rows),
                    "ids": [int(row["id"]) for row in new_saved_rows],
                },
                failure_reason="Saved Messages does not contain exactly the three task outputs",
            )
        )

        first_note_path = fsnotes_documents / FIRST_NOTE_NAME
        second_note_path = fsnotes_documents / SECOND_NOTE_NAME
        first_note_bytes = first_note_path.read_bytes() if first_note_path.is_file() else b""
        second_note_bytes = second_note_path.read_bytes() if second_note_path.is_file() else b""
        first_note_lines = cls._logical_lines(first_note_bytes)
        second_note_lines = cls._logical_lines(second_note_bytes)
        first_note_stat = cls._file_times(first_note_path)
        second_note_stat = cls._file_times(second_note_path)

        new_markdown_paths = [
            path
            for path in fsnotes_documents.glob("*.markdown")
            if path.is_file()
            and max(cls._file_times(path).values()) > fsnotes_baseline_max_timestamp
        ]
        expected_note_names = {FIRST_NOTE_NAME, SECOND_NOTE_NAME}
        observed_note_names = {path.name for path in new_markdown_paths}
        checks.append(
            cls._check(
                "fsnotes_output_count",
                observed_note_names == expected_note_names,
                steps=[4, 71],
                dimension="final_object",
                expected=sorted(expected_note_names),
                observed=sorted(observed_note_names),
                failure_reason="post-baseline FSNotes Markdown objects are missing, extra, or misnamed",
            )
        )

        first_new = (
            first_note_path.is_file()
            and first_note_stat["birthtime"] > fsnotes_baseline_max_timestamp
            and first_note_stat["mtime"] > fsnotes_baseline_max_timestamp
            and first_note_stat["birthtime"] > boot_timestamp
            and first_note_stat["mtime"] > boot_timestamp
        )
        checks.append(
            cls._check(
                "first_note_object_new",
                first_new,
                steps=[3, 4],
                dimension="final_object",
                expected={
                    "filename": FIRST_NOTE_NAME,
                    "created_and_modified_after_fsnotes_baseline": fsnotes_baseline_max_timestamp,
                    "created_and_modified_after_current_boot": boot_timestamp,
                },
                observed={"exists": first_note_path.is_file(), **first_note_stat},
                failure_reason="the first exact FSNotes object is missing or not fresh in the current boot session",
            )
        )
        second_new = (
            second_note_path.is_file()
            and second_note_stat["birthtime"] > fsnotes_baseline_max_timestamp
            and second_note_stat["mtime"] > fsnotes_baseline_max_timestamp
            and second_note_stat["birthtime"] > boot_timestamp
            and second_note_stat["mtime"] > boot_timestamp
        )
        checks.append(
            cls._check(
                "second_note_object_new",
                second_new,
                steps=[70, 71],
                dimension="final_object",
                expected={
                    "filename": SECOND_NOTE_NAME,
                    "created_and_modified_after_fsnotes_baseline": fsnotes_baseline_max_timestamp,
                    "created_and_modified_after_current_boot": boot_timestamp,
                },
                observed={"exists": second_note_path.is_file(), **second_note_stat},
                failure_reason="the second exact FSNotes object is missing or not fresh in the current boot session",
            )
        )

        selected_sources: dict[str, dict[str, Any]] = {}
        first_lines_for_matching = first_note_lines or []
        for spec in SOURCE_SPECS:
            candidates = [
                row
                for row in baseline_rows
                if str(row["chat_name"]) == str(spec["chat"])
                and str(spec["token"]) in str(row["txt"])
                and str(row["txt"]) in first_lines_for_matching
            ]
            selected = candidates[0] if len(candidates) == 1 else None
            if selected is not None:
                selected_sources[str(spec["key"])] = cls._message_summary(selected)
            checks.append(
                cls._check(
                    f"source_provenance:{spec['key']}",
                    selected is not None,
                    steps=list(spec["steps"]),
                    dimension="source_process",
                    expected={
                        "chat": spec["chat"],
                        "token": spec["token"],
                        "complete_message_as_one_exact_line": True,
                    },
                    observed=[cls._message_summary(row) for row in candidates],
                    failure_reason=(
                        "the first note does not contain exactly one complete baseline message "
                        f"from {spec['chat']} as a dedicated line"
                    ),
                )
            )

        source_keys = [str(spec["key"]) for spec in SOURCE_SPECS]
        source_line_indexes = [
            first_lines_for_matching.index(str(selected_sources[key]["text"]))
            for key in source_keys
            if key in selected_sources
        ]
        source_order_ok = (
            len(source_line_indexes) == len(source_keys)
            and source_line_indexes == sorted(source_line_indexes)
            and len(set(source_line_indexes)) == len(source_keys)
        )
        checks.append(
            cls._check(
                "source_messages_in_instruction_order",
                source_order_ok,
                steps=[18, 29, 40, 56],
                dimension="source_process",
                expected=[str(spec["chat"]) for spec in SOURCE_SPECS],
                observed={
                    "source_keys": source_keys,
                    "line_indexes": source_line_indexes,
                    "selected": selected_sources,
                },
                failure_reason="the four complete source lines are missing, duplicated, or not in Mei/Alice/Bob/Nora order",
            )
        )

        expected_first_lines = cls._resolve_line_spec(FIRST_NOTE_LINE_SPEC, selected_sources)
        expected_first_bytes = cls._expected_bytes(expected_first_lines)
        expected_second_lines = list(SECOND_NOTE_LINES)
        expected_second_bytes = cls._expected_bytes(expected_second_lines)
        first_exact = expected_first_bytes is not None and first_note_bytes == expected_first_bytes
        checks.append(
            cls._check(
                "first_note_exact_bytes_and_newlines",
                first_exact,
                steps=[3, 4, 5, 6, 7, 14, 15, 16, 18, 25, 26, 27, 29, 36, 37, 38, 40, 52, 53, 54, 56, 57, 58, 59, 60, 61, 62],
                dimension="content_parameter",
                expected={
                    "lines": expected_first_lines,
                    "encoding": "UTF-8",
                    "lf_count": 12,
                    "trailing_lf": False,
                    "newline_steps": list(NOTE_NEWLINE_STEPS[:-1]),
                    "create_return_step": 4,
                },
                observed={
                    "filename": first_note_path.name,
                    "utf8_valid": first_note_lines is not None,
                    "lines": first_note_lines,
                    "size": len(first_note_bytes),
                    "lf_count": first_note_bytes.count(b"\n"),
                    "contains_cr": b"\r" in first_note_bytes,
                    "trailing_lf": first_note_bytes.endswith(b"\n"),
                },
                failure_reason="the first note has missing, extra, repeated, reordered, or wrongly separated bytes",
            )
        )
        second_exact = second_note_bytes == expected_second_bytes
        checks.append(
            cls._check(
                "second_note_exact_bytes_and_newlines",
                second_exact,
                steps=[70, 71, 72, 73, 74],
                dimension="content_parameter",
                expected={
                    "lines": expected_second_lines,
                    "encoding": "UTF-8",
                    "lf_count": 1,
                    "trailing_lf": False,
                    "newline_step": 73,
                    "create_return_step": 71,
                },
                observed={
                    "filename": second_note_path.name,
                    "utf8_valid": second_note_lines is not None,
                    "lines": second_note_lines,
                    "size": len(second_note_bytes),
                    "lf_count": second_note_bytes.count(b"\n"),
                    "contains_cr": b"\r" in second_note_bytes,
                    "trailing_lf": second_note_bytes.endswith(b"\n"),
                },
                failure_reason="the second note has missing, extra, repeated, reordered, or wrongly separated bytes",
            )
        )

        authored_rows = [
            row
            for row in new_saved_rows
            if int(row["type"]) == 10
            and int(row["state"]) == sent_state
            and str(row["txt"]) == AUTHORED_SUMMARY
            and int(row["timestamp"] or 0) > baseline_max_timestamp
        ]
        authored_row = authored_rows[0] if len(authored_rows) == 1 else None
        checks.append(
            cls._check(
                "authored_saved_message",
                authored_row is not None,
                steps=[43, 44, 45],
                dimension="final_object",
                expected={
                    "exact_text": AUTHORED_SUMMARY,
                    "state": sent_state,
                    "timestamp_after": baseline_max_timestamp,
                },
                observed=[cls._message_summary(row) for row in authored_rows],
                failure_reason="the exact new sent Ops gate summary is missing, duplicated, stale, or unsent",
            )
        )

        attachment_rows = [row for row in new_saved_rows if int(row["type"]) == 60]
        first_attachment = cls._unique_attachment(attachment_rows, FIRST_NOTE_NAME)
        second_attachment = cls._unique_attachment(attachment_rows, SECOND_NOTE_NAME)
        first_attachment_evidence = cls._attachment_evidence(
            db_path=db_path,
            row=first_attachment,
            note_path=first_note_path,
            expected_filename=FIRST_NOTE_NAME,
            expected_bytes=expected_first_bytes,
            sent_state=sent_state,
            baseline_max_timestamp=baseline_max_timestamp,
        )
        second_attachment_evidence = cls._attachment_evidence(
            db_path=db_path,
            row=second_attachment,
            note_path=second_note_path,
            expected_filename=SECOND_NOTE_NAME,
            expected_bytes=expected_second_bytes,
            sent_state=sent_state,
            baseline_max_timestamp=baseline_max_timestamp,
        )
        checks.append(
            cls._check(
                "first_saved_attachment",
                bool(first_attachment_evidence["pass"]),
                steps=list(range(63, 68)),
                dimension="final_object",
                expected="one sent post-baseline first-note attachment with the exact canonical bytes",
                observed=first_attachment_evidence,
                failure_reason="the first attachment is missing, unsafe, stale, unsent, misnamed, or byte-different",
            )
        )
        checks.append(
            cls._check(
                "second_saved_attachment",
                bool(second_attachment_evidence["pass"]),
                steps=list(range(75, 80)),
                dimension="final_object",
                expected="one sent post-baseline second-note attachment with the exact canonical bytes",
                observed=second_attachment_evidence,
                failure_reason="the second attachment is missing, unsafe, stale, unsent, misnamed, or byte-different",
            )
        )

        ordered_rows = [authored_row, first_attachment, second_attachment]
        ordered_ids = [int(row["id"]) for row in ordered_rows if row is not None]
        ordered_timestamps = [int(row["timestamp"] or 0) for row in ordered_rows if row is not None]
        new_ids = [int(row["id"]) for row in new_saved_rows]
        saved_order_ok = (
            len(ordered_ids) == 3
            and new_ids == ordered_ids
            and all(left < right for left, right in zip(ordered_ids, ordered_ids[1:]))
            and all(
                left < right
                for left, right in zip(ordered_timestamps, ordered_timestamps[1:])
            )
        )
        checks.append(
            cls._check(
                "saved_messages_business_order",
                saved_order_ok,
                steps=[45, 67, 79],
                dimension="source_process",
                expected="exactly authored summary < first attachment < second attachment",
                observed={
                    "all_new_message_ids": new_ids,
                    "ordered_message_ids": ordered_ids,
                    "ordered_timestamps": ordered_timestamps,
                },
                failure_reason="the three outputs are missing, extra, duplicated, or not strictly ordered",
            )
        )

        authored_timestamp = cls._row_timestamp(authored_row)
        first_attachment_timestamp = cls._row_timestamp(first_attachment)
        second_attachment_timestamp = cls._row_timestamp(second_attachment)
        cross_app_order_ok = (
            first_new
            and second_new
            and first_note_stat["birthtime"] < authored_timestamp
            and authored_timestamp < first_note_stat["mtime"]
            and first_note_stat["mtime"] < first_attachment_timestamp
            and first_attachment_timestamp < second_note_stat["birthtime"]
            and second_note_stat["birthtime"] <= second_note_stat["mtime"]
            and second_note_stat["mtime"] < second_attachment_timestamp
        )
        checks.append(
            cls._check(
                "cross_app_creation_and_share_order",
                cross_app_order_ok,
                steps=[4, 45, 62, 67, 71, 74, 79],
                dimension="source_process",
                expected=(
                    "first note birth < summary send < first note final mtime < first share < "
                    "second note birth <= second note final mtime < second share"
                ),
                observed={
                    "first_note": first_note_stat,
                    "summary_timestamp": authored_timestamp or None,
                    "first_attachment_timestamp": first_attachment_timestamp or None,
                    "second_note": second_note_stat,
                    "second_attachment_timestamp": second_attachment_timestamp or None,
                },
                failure_reason="the required cross-app creation, edit, and share chronology is not proven",
            )
        )

        first_hash = cls._sha256_bytes(first_note_bytes)
        second_hash = cls._sha256_bytes(second_note_bytes)
        first_blob_path = first_attachment_evidence.get("blob_path")
        second_blob_path = second_attachment_evidence.get("blob_path")
        first_blob_hash = first_attachment_evidence.get("blob_sha256")
        second_blob_hash = second_attachment_evidence.get("blob_sha256")
        distinct_ok = (
            first_note_path.is_file()
            and second_note_path.is_file()
            and first_note_path.name != second_note_path.name
            and first_hash != second_hash
            and bool(first_blob_path)
            and bool(second_blob_path)
            and first_blob_path != second_blob_path
            and bool(first_blob_hash)
            and bool(second_blob_hash)
            and first_blob_hash != second_blob_hash
            and len(set(ordered_ids)) == 3
        )
        checks.append(
            cls._check(
                "two_notes_and_attachments_distinct",
                distinct_ok,
                steps=list(range(68, 80)),
                dimension="final_object",
                expected="distinct note names, note hashes, blob paths, blob hashes, and message ids",
                observed={
                    "first_note_name": first_note_path.name,
                    "second_note_name": second_note_path.name,
                    "first_note_sha256": first_hash,
                    "second_note_sha256": second_hash,
                    "first_blob_path": first_blob_path,
                    "second_blob_path": second_blob_path,
                    "first_blob_sha256": first_blob_hash,
                    "second_blob_sha256": second_blob_hash,
                    "message_ids": ordered_ids,
                },
                failure_reason="the two notes, blobs, or output messages are not independently distinct",
            )
        )

        observed = {
            "database_path": str(db_path),
            "fsnotes_documents": str(fsnotes_documents),
            "saved_messages_chat_id": self_chat_id,
            "minimum_message_id": minimum_message_id,
            "baseline_max_timestamp": baseline_max_timestamp,
            "fsnotes_baseline_max_timestamp": fsnotes_baseline_max_timestamp,
            "new_saved_messages": [cls._message_summary(row) for row in new_saved_rows],
            "selected_source_messages": selected_sources,
            "first_note": {
                "path": str(first_note_path),
                "sha256": first_hash,
                "logical_lines": first_note_lines,
                **first_note_stat,
            },
            "second_note": {
                "path": str(second_note_path),
                "sha256": second_hash,
                "logical_lines": second_note_lines,
                **second_note_stat,
            },
        }
        return checks, observed

    @classmethod
    def _result(
        cls,
        *,
        status: EvalStatus,
        message: str,
        udid: str,
        checks: list[dict[str, Any]],
        observed: Mapping[str, Any],
    ) -> EvalResult:
        failures = [check for check in checks if not check["pass"]]
        return EvalResult(
            status=status,
            message=message,
            metadata={
                "task_id": TASK_ID,
                "udid": udid,
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "checks": checks,
                "failures": failures,
                "observed": dict(observed),
                "step_coverage": cls._step_coverage(checks),
                "coverage_summary": {
                    "instruction_steps": 79,
                    "mapped_steps": 79,
                    "durable_or_compound_steps": len(DURABLE_OR_COMPOUND_STEPS),
                    "required_navigation_steps": 79 - len(DURABLE_OR_COMPOUND_STEPS),
                    "final_ui": "not_required_after_terminal_share_submission",
                    "required_typed_steps": {
                        "steps": list(REQUIRED_TYPED_STEPS),
                        "handling": "required_in_complete_canonical_bytes_and_byte-identical_attachments",
                    },
                    "required_newline_steps": {
                        "steps": list(NOTE_NEWLINE_STEPS),
                        "handling": "required_by_complete_line_array_and_exact_LF_bytes",
                    },
                },
                "verifier_rules": [
                    "Human eval-only and automatic execution use this identical evaluator and ruleset digest.",
                    "The two Markdown files must match complete canonical UTF-8 bytes with exact line arrays and no extra bytes.",
                    "Every source message must be one complete line from the named baseline chat in Mei, Alice, Bob, Nora order.",
                    "Both files must be fresh in the bound boot session and satisfy the cross-app creation/edit/send chronology.",
                    "Saved Messages must contain exactly the authored summary followed by two safe byte-identical attachments.",
                    "No final UI state is required after the terminal Share submission.",
                ],
            },
        )

    @classmethod
    def _step_coverage(cls, checks: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        checks_by_name = {str(check["name"]): check for check in checks}
        coverage: list[dict[str, Any]] = []
        for group in STEP_GROUPS:
            checkpoint_names = list(group["checkpoint_names"])
            group_passed = all(
                name in checks_by_name and bool(checks_by_name[name].get("pass"))
                for name in checkpoint_names
            )
            for step in group["steps"]:
                coverage.append(
                    {
                        "step": step,
                        "role": (
                            "durable_or_compound_effect"
                            if step in DURABLE_OR_COMPOUND_STEPS
                            else "required_navigation"
                        ),
                        "checkpoint_names": checkpoint_names,
                        "mapping_basis": "shared_compound_final_state_and_current_session_chronology",
                        "purpose": group["purpose"],
                        "dimensions": {
                            "final_object": "covered",
                            "content_parameter": "covered_by_exact_bytes",
                            "source_process": "covered_by_provenance_and_order",
                            "final_ui": "not_applicable_after_terminal_submission",
                        },
                        "pass": group_passed,
                    }
                )
        return sorted(coverage, key=lambda item: int(item["step"]))

    @staticmethod
    def _check(
        name: str,
        passed: bool,
        *,
        steps: list[int],
        dimension: str,
        expected: Any,
        observed: Any,
        failure_reason: str,
    ) -> dict[str, Any]:
        return {
            "name": name,
            "pass": bool(passed),
            "steps": steps,
            "dimension": dimension,
            "expected": expected,
            "observed": observed,
            "failure_reason": None if passed else failure_reason,
        }

    @classmethod
    def _attachment_evidence(
        cls,
        *,
        db_path: Path,
        row: sqlite3.Row | None,
        note_path: Path,
        expected_filename: str,
        expected_bytes: bytes | None,
        sent_state: int,
        baseline_max_timestamp: int,
    ) -> dict[str, Any]:
        if row is None:
            return {"pass": False, "reason": "matching attachment row is missing or duplicated"}
        params = cls._parse_params(row["param"])
        filename = params.get("v", "")
        raw_blob = params.get("f", "")
        blob_root = (db_path.parent / "dc.db-blobs").resolve()
        blob_path: Path | None = None
        safe_blob = False
        if raw_blob.startswith("$BLOBDIR/"):
            candidate = (blob_root / raw_blob.removeprefix("$BLOBDIR/")).resolve()
            if candidate.is_relative_to(blob_root):
                blob_path = candidate
                safe_blob = True
        note_bytes = note_path.read_bytes() if note_path.is_file() else b""
        blob_bytes = blob_path.read_bytes() if blob_path is not None and blob_path.is_file() else b""
        note_hash = cls._sha256_bytes(note_bytes) if note_bytes else None
        blob_hash = cls._sha256_bytes(blob_bytes) if blob_bytes else None
        passed = (
            filename == expected_filename
            and note_path.name == expected_filename
            and int(row["state"]) == sent_state
            and int(row["timestamp"] or 0) > baseline_max_timestamp
            and safe_blob
            and blob_path is not None
            and blob_path.is_file()
            and expected_bytes is not None
            and note_bytes == expected_bytes
            and blob_bytes == expected_bytes
        )
        return {
            "pass": passed,
            "message_id": int(row["id"]),
            "filename": filename,
            "state": int(row["state"]),
            "timestamp": int(row["timestamp"] or 0),
            "blob_path": str(blob_path) if blob_path is not None else None,
            "blob_path_safe": safe_blob,
            "blob_sha256": blob_hash,
            "note_path": str(note_path),
            "note_sha256": note_hash,
            "canonical_sha256": (
                cls._sha256_bytes(expected_bytes) if expected_bytes is not None else None
            ),
        }

    @classmethod
    def _unique_attachment(
        cls, rows: Sequence[sqlite3.Row], expected_filename: str
    ) -> sqlite3.Row | None:
        matches = [
            row
            for row in rows
            if cls._param_value(row["param"], "v") == expected_filename
        ]
        return matches[0] if len(matches) == 1 else None

    @staticmethod
    def _message_summary(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "id": int(row["id"]),
            "chat_id": int(row["chat_id"]),
            "chat_name": str(row["chat_name"]),
            "type": int(row["type"]),
            "state": int(row["state"]),
            "timestamp": int(row["timestamp"] or 0),
            "text": str(row["txt"]),
            "attachment_name": DeltaChatRouteApprovalStateEvaluator._param_value(
                row["param"], "v"
            ),
        }

    @staticmethod
    def _resolve_line_spec(
        spec: Sequence[tuple[str, str]], selected_sources: Mapping[str, Mapping[str, Any]]
    ) -> list[str] | None:
        lines: list[str] = []
        for kind, value in spec:
            if kind == "literal":
                lines.append(value)
            elif kind == "source" and value in selected_sources:
                lines.append(str(selected_sources[value]["text"]))
            else:
                return None
        return lines

    @staticmethod
    def _expected_bytes(lines: Sequence[str] | None) -> bytes | None:
        if lines is None:
            return None
        return "\n".join(lines).encode("utf-8")

    @staticmethod
    def _logical_lines(payload: bytes) -> list[str] | None:
        try:
            return payload.decode("utf-8").split("\n")
        except UnicodeDecodeError:
            return None

    @staticmethod
    def _file_times(path: Path) -> dict[str, float]:
        if not path.is_file():
            return {"birthtime": 0.0, "mtime": 0.0}
        stat = path.stat()
        return {
            "birthtime": float(getattr(stat, "st_birthtime", stat.st_mtime)),
            "mtime": float(stat.st_mtime),
        }

    @staticmethod
    def _row_timestamp(row: sqlite3.Row | None) -> int:
        return int(row["timestamp"] or 0) if row is not None else 0

    @staticmethod
    def _int_param(params: Mapping[str, Any], key: str) -> int:
        try:
            return int(params[key])
        except (KeyError, TypeError, ValueError):
            return -1

    @staticmethod
    def _resolve_fsnotes_documents(*, udid: str, bundle_id: str) -> Path:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "data"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode == 0 and proc.stdout.strip():
            root = Path(proc.stdout.strip()).resolve()
        else:
            container = _find_app_data_container_by_metadata(udid=udid, bundle_id=bundle_id)
            if container is None:
                raise RuntimeError(f"FSNotes data-container lookup failed: {proc.stderr.strip()}")
            root = container.resolve()
        documents = (root / "Documents").resolve()
        if not documents.is_dir():
            raise FileNotFoundError(f"FSNotes Documents directory is missing: {documents}")
        return documents

    @staticmethod
    def _read_app_identity(udid: str, bundle_id: str) -> dict[str, str]:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "app"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0 or not proc.stdout.strip():
            raise RuntimeError(
                f"application container lookup failed for {bundle_id}: {proc.stderr.strip()}"
            )
        info_path = Path(proc.stdout.strip()).resolve() / "Info.plist"
        if not info_path.is_file():
            raise FileNotFoundError(f"application Info.plist is missing: {info_path}")
        with info_path.open("rb") as handle:
            info = plistlib.load(handle)
        return {
            "bundle_id": str(info.get("CFBundleIdentifier") or ""),
            "short_version": str(info.get("CFBundleShortVersionString") or ""),
            "build_version": str(info.get("CFBundleVersion") or ""),
        }

    @staticmethod
    def _read_boot_timestamp(udid: str, seed_boundary: float) -> float:
        parsed = uuid.UUID(udid)
        canonical_udid = str(parsed).upper()
        simulator_root = (
            Path.home() / "Library" / "Developer" / "CoreSimulator" / "Devices"
        ).resolve()
        device_root = (simulator_root / canonical_udid).resolve()
        if not device_root.is_relative_to(simulator_root):
            raise RuntimeError("bound simulator UDID resolves outside CoreSimulator Devices")
        device_plist = device_root / "device.plist"
        with device_plist.open("rb") as handle:
            metadata = plistlib.load(handle)
        booted_at = metadata.get("lastBootedAt")
        if not isinstance(booted_at, datetime):
            return float(seed_boundary)
        if booted_at.tzinfo is None:
            booted_at = booted_at.replace(tzinfo=timezone.utc)
        return max(float(booted_at.timestamp()), float(seed_boundary))

    @staticmethod
    @contextmanager
    def _sqlite_snapshot(db_path: Path) -> Iterator[Path]:
        """Copy dc.db and its WAL/SHM sidecars into a temporary read-only query snapshot."""

        with tempfile.TemporaryDirectory(prefix="ios-deltachat-route-eval-") as temp_dir:
            snapshot = Path(temp_dir) / db_path.name
            shutil.copy2(db_path, snapshot)
            for suffix in ("-wal", "-shm"):
                sidecar = Path(f"{db_path}{suffix}")
                if sidecar.exists():
                    shutil.copy2(sidecar, Path(f"{snapshot}{suffix}"))
            yield snapshot

    @staticmethod
    def _parse_params(raw: Any) -> dict[str, str]:
        values: dict[str, str] = {}
        for line in str(raw or "").splitlines():
            if "=" in line:
                key, value = line.split("=", 1)
                values[key] = value
        return values

    @classmethod
    def _param_value(cls, raw: Any, key: str) -> str:
        return cls._parse_params(raw).get(key, "")

    @staticmethod
    def _sha256_bytes(payload: bytes | None) -> str | None:
        if payload is None:
            return None
        return hashlib.sha256(payload).hexdigest()
